package bo.edu.umss.mercado;

import bo.edu.umss.mercado.data.CanonicalJson;
import bo.edu.umss.mercado.reporting.*;
import bo.edu.umss.mercado.statistics.*;
import bo.edu.umss.mercado.survey.*;
import bo.edu.umss.mercado.response.SurveyResponseRepository;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.LinkedMultiValueMap;
import org.springframework.test.web.servlet.MockMvc;
import static org.assertj.core.api.Assertions.*;
import static org.hamcrest.Matchers.containsString;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:template-management-tests;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password="})
@AutoConfigureMockMvc @ActiveProfiles("test") @WithMockUser(username="template-admin",roles="ADMIN") @Transactional
class ReportTemplateManagementIntegrationTest {
    static final String ACTOR="template-admin";
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired DraftSurveyService drafts;@Autowired SurveyPublicationService publications;@Autowired SurveyValidator validator;@Autowired SurveyResponseRepository responses;@Autowired WorkspaceResultsService results;@Autowired GenericAnalysisService analyses;@Autowired ReportService reports;@Autowired ReportPresentationTemplates templates;@Autowired TextDictionaryService dictionaries;
    String publish(){String v=drafts.create("Fuentes ficticias","Prueba",ACTOR);drafts.section(v,0,null,"Datos",ACTOR);String section=drafts.get(v).sections().getFirst().id();drafts.question(v,1,section,new Question("opinion","Datos","Opinión libre","textarea",false,List.of(),null,null,0,1,"",null,null),true,ACTOR);publications.publish(v,2,ACTOR);return v;}
    void response(String v){var values=new LinkedMultiValueMap<String,String>();values.set("consent","SI");values.set("opinion","IA: contenido ficticio de la respuesta");responses.savePublished(v,UUID.randomUUID().toString(),validator.validate(publications.get(v).content().definition(),values));}
    @SuppressWarnings("unchecked") Map<String,Object> json(String value){return CanonicalJson.read(value,Map.class);}
    String open(MockHttpSession session,String id,String mode,String type,String version,String cut)throws Exception{return mvc.perform(post("/admin/plantillas-reportes/abrir").session(session).with(csrf()).param("templateId",id).param("mode",mode).param("sourceType",type).param("versionId",version).param("cutId",cut)).andExpect(status().is3xxRedirection()).andReturn().getResponse().getRedirectedUrl();}
    Map<String,Object> bootstrap(MockHttpSession session,String url)throws Exception{return json(mvc.perform(get(url).session(session)).andExpect(status().isOk()).andExpect(view().name("report-customizer")).andReturn().getModelAndView().getModel().get("customBootstrap").toString());}
    ReportCustomization.Configuration configuration(Map<String,Object> bootstrap){return CanonicalJson.read(CanonicalJson.json(bootstrap.get("configuration")),ReportCustomization.Configuration.class);}
    String save(ReportCustomization.Configuration config,String id,String hash,String name)throws Exception {var preview=reports.preview(config,ACTOR);var body=Map.of("configuration",config,"expectedHash",CanonicalJson.hash(preview),"templateId",id,"templateHash",hash,"name",name);return (String)json(mvc.perform(post("/admin/plantillas-reportes/guardar").with(csrf()).contentType("application/json").content(CanonicalJson.json(body))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("id");}
    @Test void templateUsesTotalsOrFrozenCutAndCanBeEditedDuplicatedAndDeletedWithoutChangingReports()throws Exception{
        String v=publish();var emptyFrame=results.load(publications.get(v).slug(),List.of(v),"","",ACTOR);String emptyCut=results.save(emptyFrame,"Corte vacío",ACTOR);response(v);response(v);dictionaries.saveGlobal(0,"inteligencia artificial=ia|inteligencia artificial",ACTOR);var version=publications.get(v);var frame=results.load(version.slug(),List.of(v),"","",ACTOR);String cut=results.save(frame,"Corte de dos envíos",ACTOR);response(v);
        mvc.perform(get("/admin/plantillas-reportes/nueva").with(anonymous())).andExpect(status().is3xxRedirection());mvc.perform(get("/admin/plantillas-reportes/nueva").with(user("viewer").roles("USER"))).andExpect(status().isForbidden());
        mvc.perform(post("/admin/plantillas-reportes/abrir").param("mode","create").param("sourceType","total").param("versionId",v)).andExpect(status().isForbidden());
        mvc.perform(get("/admin/reportes/plantillas/nueva")).andExpect(status().isOk()).andExpect(view().name("report-template-source")).andExpect(content().string(containsString("Corte de datos guardado")));
        var session=new MockHttpSession();String createUrl=open(session,"","create","total",v,"");var base=configuration(bootstrap(session,createUrl));assertThat(((Map<?,?>)analyses.get(base.analysisId()).get("result")).get("submission_count")).isEqualTo(3);
        var config=new ReportCustomization.Configuration(base.analysisId(),"Título de presentación","Introducción",true,true,true,"Comentario del reporte, no de plantilla",List.of(new ReportCustomization.Question("opinion",true,"Título de la pregunta","Nota de este reporte",List.of("text-table","text-bars","text-pie","text-donut"))),List.of());
        String id=save(config,"","","Plantilla de prueba");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM generated_report",Integer.class)).isZero();var stored=templates.stored(id);assertThat(stored.definition().configuration().analysisId()).isEmpty();assertThat(stored.definition().configuration().comment()).isEmpty();assertThat(CanonicalJson.json(stored)).doesNotContain("contenido ficticio de la respuesta");
        var emptyUsed=configuration(bootstrap(session,open(session,id,"use","cut","",emptyCut)));var emptyPreview=reports.preview(emptyUsed,ACTOR);assertThat(((Map<?,?>)emptyPreview.get("display_result")).get("submission_count")).isEqualTo(0);mvc.perform(post("/admin/reportes/personalizar/vista-previa").with(csrf()).contentType("application/json").content(CanonicalJson.json(emptyUsed))).andExpect(status().isOk()).andExpect(content().string(containsString("Sin coincidencias en esta fuente")));
        var used=configuration(bootstrap(session,open(session,id,"use","cut","",cut)));assertThat(((Map<?,?>)analyses.get(used.analysisId()).get("result")).get("submission_count")).isEqualTo(2);assertThat(used.questions().getFirst().representations()).containsExactly("text-table","text-bars","text-pie","text-donut");
        var preview=reports.preview(used,ACTOR);String report=reports.generateCustomized(used,CanonicalJson.hash(preview),ACTOR);var total=configuration(bootstrap(session,open(session,id,"use","total",v,"")));assertThat(((Map<?,?>)analyses.get(total.analysisId()).get("result")).get("submission_count")).isEqualTo(3);
        String editUrl=open(session,id,"edit","cut","",cut);var editBootstrap=bootstrap(session,editUrl);assertThat(((Map<?,?>)editBootstrap.get("templateEditor")).get("id")).isEqualTo(id);mvc.perform(get(editUrl).session(new MockHttpSession())).andExpect(status().isBadRequest());
        var edited=new ReportCustomization.Configuration(used.analysisId(),"Título editado",used.introduction(),true,true,true,"",used.questions(),List.of());assertThat(save(edited,id,stored.hash(),"Plantilla editada")).isEqualTo(id);var current=templates.stored(id);
        var stale=Map.of("configuration",edited,"expectedHash",CanonicalJson.hash(reports.preview(edited,ACTOR)),"templateId",id,"templateHash",stored.hash(),"name","Cambio obsoleto");mvc.perform(post("/admin/plantillas-reportes/guardar").with(csrf()).contentType("application/json").content(CanonicalJson.json(stale))).andExpect(status().isConflict());
        mvc.perform(post("/admin/plantillas-reportes/"+id+"/duplicar").param("expectedHash",current.hash()).param("name","Copia")).andExpect(status().isForbidden());var copied=mvc.perform(post("/admin/plantillas-reportes/"+id+"/duplicar").with(csrf()).param("expectedHash",current.hash()).param("name","Copia editable")).andExpect(status().is3xxRedirection()).andReturn().getResponse().getRedirectedUrl();String copy=copied.split("/")[3];assertThat(copy).isNotEqualTo(id);assertThat(templates.stored(copy).definition()).isEqualTo(current.definition());
        save(edited,copy,templates.stored(copy).hash(),"Copia modificada");assertThat(templates.stored(id).name()).isEqualTo("Plantilla editada");
        mvc.perform(post("/admin/plantillas-reportes/"+id+"/eliminar").with(csrf()).param("expectedHash",current.hash())).andExpect(status().isBadRequest());mvc.perform(post("/admin/plantillas-reportes/"+id+"/eliminar").with(csrf()).param("expectedHash",current.hash()).param("confirm","true")).andExpect(status().is3xxRedirection());assertThatThrownBy(()->templates.stored(id)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThat(templates.stored(copy)).isNotNull();assertThat(CanonicalJson.hash(reports.get(report).get("content"))).isEqualTo(CanonicalJson.hash(preview));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM report_template_management_event",Integer.class)).isGreaterThanOrEqualTo(5);
        var dir=Path.of(".codex-tmp/template-management-browser");Files.createDirectories(dir);Files.writeString(dir.resolve("create.html"),mvc.perform(get(createUrl).session(session)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));Files.writeString(dir.resolve("create-preview.json"),mvc.perform(post("/admin/reportes/personalizar/vista-previa").with(csrf()).contentType("application/json").content(CanonicalJson.json(base))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));Files.writeString(dir.resolve("library.html"),mvc.perform(get("/admin/reportes")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));Files.writeString(dir.resolve("source.html"),mvc.perform(get("/admin/plantillas-reportes/"+copy+"/usar")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));String copyEditor=open(session,copy,"edit","cut","",cut);Files.writeString(dir.resolve("editor.html"),mvc.perform(get(copyEditor).session(session)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));var copyConfig=configuration(bootstrap(session,copyEditor));Files.writeString(dir.resolve("preview.json"),mvc.perform(post("/admin/reportes/personalizar/vista-previa").with(csrf()).contentType("application/json").content(CanonicalJson.json(copyConfig))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));
    }
    @Test void oldTemplatesOpenInCurrentEditorAndCanLeaveLibraryWithoutBreakingHistoricalReports()throws Exception{
        String v=publish();response(v);var frame=results.load(publications.get(v).slug(),List.of(v),"","",ACTOR);String analysis=results.materialize(frame,ACTOR);String root=reports.createTemplate(new ReportService.Template("Plantilla anterior","Texto",List.of("COMENTARIOS","DESCRIPTIVOS"),false),ACTOR);var legacy=reports.latest(root);String report=reports.generate(legacy.id(),analysis,List.of(),"Comentario histórico",ACTOR);var original=reports.get(report);
        mvc.perform(get("/admin/reportes/plantillas/"+root+"/editar")).andExpect(status().isOk()).andExpect(view().name("report-template-source"));var session=new MockHttpSession();var bootstrap=bootstrap(session,open(session,"legacy-"+root,"edit","total",v,""));assertThat(((Map<?,?>)bootstrap.get("templateEditor")).get("id")).isEqualTo("");var config=configuration(bootstrap);assertThat(config.title()).isEqualTo("Plantilla anterior");String converted=save(config,"","","Plantilla actual");assertThat(templates.stored(converted)).isNotNull();
        mvc.perform(post("/admin/plantillas-reportes/legacy-"+root+"/eliminar").with(csrf()).param("expectedHash",legacy.hash()).param("confirm","true")).andExpect(status().is3xxRedirection());mvc.perform(get("/admin/plantillas-reportes/legacy-"+root+"/usar")).andExpect(status().isNotFound());assertThat(CanonicalJson.hash(reports.get(report))).isEqualTo(CanonicalJson.hash(original));assertThat(reports.latest(root)).isNotNull();
    }
}